class ArgumentParser:
    DEFAULT_TYPE = str

    def __init__(self):
        self._arguments = {}
        self._required = set()
        self._types = {}

    def parse_arguments(self, command_string):
        args = command_string.split()[1:]
        for i in range(len(args)):
            arg = args[i]
            if arg.startswith('--'):
                self._process_long_argument(arg)
            elif arg.startswith('-'):
                self._process_short_argument(arg, args, i)
        missing_args = self._get_missing_required_arguments()
        if missing_args:
            return False, missing_args

        return True, None

    def _process_long_argument(self, arg):
        key_value = arg[2:].split('=')
        if len(key_value) == 2:
            self._arguments[key_value[0]] = self._convert_type(key_value[0], key_value[1])
        else:
            self._arguments[key_value[0]] = True

    def _process_short_argument(self, arg, args, index):
        key = arg[1:]
        if index + 1 < len(args) and not args[index + 1].startswith('-'):
            self._arguments[key] = self._convert_type(key, args[index + 1])
        else:
            self._arguments[key] = True

    def _get_missing_required_arguments(self):
        return self._required - set(self._arguments.keys())

    def get_argument(self, key):
        return self._arguments.get(key)

    def add_argument(self, arg, required=False, arg_type=DEFAULT_TYPE):
        if required:
            self._required.add(arg)
        self._types[arg] = arg_type

    def _convert_type(self, arg, value):
        try:
            return self._types[arg](value)
        except (ValueError, KeyError):
            return value
